const searches = [
  'software companies',
  'artificial intelligence companies',
  'cybersecurity companies',
  'cloud computing companies',
  'telecommunications companies',
  'robotics companies'
];

return [{
  json: {
    actorInput: {
      searchStringsArray: searches,
      locationQuery: 'Ottawa, Ontario, Canada',
      maxCrawledPlacesPerSearch: 20,
      language: 'en',
      searchMatching: 'all',
      website: 'allPlaces',
      skipClosedPlaces: false,
      scrapePlaceDetailPage: false,
      scrapeContacts: false,
      includeWebResults: false,
      scrapeDirectories: false,
      maxReviews: 0
    }
  }
}];

const payloads = [];
for (const item of $input.all()) {
  const payload = item.json?.body ?? item.json;
  if (Array.isArray(payload)) payloads.push(...payload);
  else payloads.push(payload);
}

const clean = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();
const domainFromUrl = (value) => {
  if (!value) return '';
  try {
    const u = new URL(/^https?:\/\//i.test(value) ? value : `https://${value}`);
    return u.hostname.toLowerCase().replace(/^www\./, '');
  } catch {
    return '';
  }
};
const normalizeOrg = (v) => clean(v)
  .toLowerCase()
  .replace(/\b(incorporated|corporation|company|limited|inc|ltd|corp|co)\b\.?/g, '')
  .replace(/[^a-z0-9]+/g, ' ')
  .trim();

return payloads
  .filter(Boolean)
  .map((p) => {
    const organization = clean(p.title ?? p.name);
    const website = clean(p.website ?? p.websiteUrl);
    const address = clean(p.address ?? p.street);
    const domain = domainFromUrl(website);
    const placeId = clean(p.placeId ?? p.place_id);
    const mapsUrl = clean(p.url ?? p.googleMapsUrl);
    const query = clean(p.searchString ?? p.searchQuery ?? p.searchTerm);
    const closed = p.permanentlyClosed ? 'Permanently Closed' :
      p.temporarilyClosed ? 'Temporarily Closed' :
      clean(p.businessStatus ?? 'Open / Unknown');
    const dedupKey = domain
      ? `domain:${domain}`
      : placeId
        ? `place:${placeId}`
        : `org:${normalizeOrg(organization)}|${address.toLowerCase()}`;

    return {
      json: {
        'Search Query': query,
        Organization: organization,
        Category: clean(p.categoryName ?? p.category),
        Website: website,
        Domain: domain,
        'Public Phone': clean(p.phone ?? p.phoneNumber),
        Address: address,
        City: clean(p.city),
        Province: clean(p.state ?? p.province),
        'Postal Code': clean(p.postalCode ?? p.zip),
        'Google Place ID': placeId,
        'Google Maps URL': mapsUrl,
        Rating: p.totalScore ?? p.rating ?? '',
        'Review Count': p.reviewsCount ?? p.numberOfReviews ?? '',
        'Closed Status': closed,
        'Date Scraped': new Date().toISOString(),
        'Dedup Key': dedupKey,
        'Run Notes': ''
      }
    };
  })
  .filter((item) => item.json.Organization);

const categoryRules = [
  ['AI & Data', /\b(ai|artificial intelligence|machine learning|data|analytics)\b/i],
  ['Cybersecurity', /\b(cyber|security)\b/i],
  ['Cloud & DevOps', /\b(cloud|devops|hosting|infrastructure)\b/i],
  ['Telecom & Networking', /\b(telecom|network|wireless|5g)\b/i],
  ['Semiconductors & Photonics', /\b(semiconductor|photonics|chip|optical)\b/i],
  ['Robotics / Hardware / IoT', /\b(robot|hardware|iot|embedded|electronics|autonomous)\b/i],
  ['Fintech', /\b(fintech|payments|banking)\b/i],
  ['Digital Health', /\b(health|medical|medtech)\b/i],
  ['Clean Technology', /\b(clean|energy|climate|renewable)\b/i],
  ['IT Services / Consulting', /\b(it service|consulting|managed service|digital transformation)\b/i],
  ['Software / SaaS', /\b(software|saas|application|platform)\b/i],
];

return $input.all()
  .filter((item) => !/Permanently Closed|Temporarily Closed/i.test(item.json['Closed Status']))
  .map((item) => {
    const x = item.json;
    const text = `${x['Search Query']} ${x.Category} ${x.Organization}`;
    let techCategory = 'Other Technology';
    for (const [category, regex] of categoryRules) {
      if (regex.test(text)) { techCategory = category; break; }
    }

    const row = {
      Organization: x.Organization,
      'Tech Category': techCategory,
      'Google Maps Listed': 'Yes',
      'Google Maps URL': x['Google Maps URL'],
      'Search Query': x['Search Query'],
      'Date Last Verified': x['Date Scraped'],
      'Lead Status': 'New',
      'Dedup Key': x['Dedup Key'],
      'Duplicate Review': 'Needs Review'
    };

    const copyIf = (key, value) => {
      if (value !== undefined && value !== null && String(value).trim() !== '') row[key] = value;
    };
    copyIf('Website', x.Website);
    copyIf('Public Phone', x['Public Phone']);
    copyIf('Address', x.Address);
    copyIf('City', x.City);
    copyIf('Province', x.Province);
    copyIf('Postal Code', x['Postal Code']);
    copyIf('Rating', x.Rating);
    copyIf('Review Count', x['Review Count']);
    copyIf('Ottawa Presence', 'Local Office');

    return { json: row };
  });
